import{z as n,x as s,o as e,c as d,q as l,j as i,D as r,d as E,s as o,S as T,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"远期测度","description":"","frontmatter":{"title":"远期测度","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/forward-measure.md","filePath":"quant/forward-measure.md","lastUpdated":1791413859000}'),m={name:"quant/forward-measure.md"};function A(p,a,_,h,u,c){const B=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="远期测度" tabindex="-1">远期测度 <a class="header-anchor" href="#远期测度" aria-label="Permalink to &quot;远期测度&quot;">​</a></h1><div class="epigraph"><p>$T$-远期测度以到期 $T$ 的零息债为计价物。该测度下，到期 $T$ 的未定权益价格是远期价格的普通期望，贴现从期望里提出。</p><footer>—— 据 Geman, El Karoui and Rochet, Journal of Applied Probability, 1995；Jamshidian, 1989；Shreve, Stochastic Calculus for Finance II, 第 9 章整理</footer></div><p>上一课<a href="/quant/lognormal-black-formula">对数正态与 Black 公式</a>在常数利率下把 \\(d_2\\) 读成 \\(Q\\) 概率。缺口是：利率一旦随机，贴现因子 \\(\\mathrm e^{-\\int r}\\) 与 \\(S_T\\) 相关，不能再写成 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\) 这种常数贴现。换计价物到零息债 \\(P(\\cdot,T)\\)，期望与贴现分离。本课只定义 \\(T\\)-远期测度，并为下一课「利率不是常数」留下接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>储蓄账户 \\(B_t=\\exp(\\int_0^t r_s\\mathrm d s)\\) 作计价物时，价格是 \\(\\mathbb E_Q[H/B_T]\\)。\\(r\\) 随机则 \\(1/B_T\\) 与 \\(H\\) 一般不独立，Black 里那个提出来的 \\(\\mathrm e^{-rT}\\) 没有了。缺口是另选计价物 \\(N_t=P(t,T)\\)（\\(T\\) 到期的零息债），定义 \\(Q^T\\sim Q\\)，使所有以 \\(N\\) 贴现的可交易资产为 \\(Q^T\\)-鞅。此时</p> \\[V_t=P(t,T)\\,\\mathbb E^{Q^T}[H\\mid\\mathcal F_t]\\qquad(H\\text{ 在 }T\\text{ 支付}). \\]<p>\\(P(t,T)\\) 可从债券市场观察，期望里不再夹随机贴现。</p><p><span class="marginnote">计价物翻译成大白话：给所有价格找一把统一的尺子。用储蓄账户当尺子，量出的是「折成今天的钱」；用 \\(T\\) 到期零息债当尺子，量出的是「折成 \\(T\\) 时刻的钱」。换尺子不改变东西的大小，只改变读数的方式——好换的尺子能让贴现从期望里整个拿出来。</span></p><h3 id="远期测度不是「把股票换成远期」的口误" tabindex="-1">远期测度不是「把股票换成远期」的口误 <a class="header-anchor" href="#远期测度不是「把股票换成远期」的口误" aria-label="Permalink to &quot;远期测度不是「把股票换成远期」的口误&quot;">​</a></h3><p>股票测度（\\(S\\) 作计价物）给出 \\(d_1\\)；\\(T\\)-远期测度给出与 \\(d_2\\) 同类的概率。两者都是计价物变换，对象不同。把「远期测度」说成「标的改成期货」，会把 \\(Q^T\\) 和期货风险中性（Black 76 在确定利率下的 \\(Q\\)）混在一条。随机利率下期货与远期还要再分，本课先钉债券计价物。</p><p><span class="marginnote">密度过程正比于 \\(P(t,T)/B_t\\) 相对其初值，即贴现债券价格。这是 RN 导数课 Bayes 公式的具体化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(P(t,T)=\\mathbb E_Q[B_t/B_T\\mid\\mathcal F_t]\\)。定义</p> \\[\\frac{\\mathrm d Q^T}{\\mathrm d Q}\\Big|_{\\mathcal F_t}=\\frac{P(t,T)/B_t}{P(0,T)}. \\]<p>则 \\(T\\) 到期的可交易支付用 \\(Q^T\\) 取期望再乘 \\(P(t,T)\\)。远期价格 \\(F(t;T)=S_t/P(t,T)\\)（合适的再投资约定下）是 \\(Q^T\\)-鞅。因此「远期对数正态」精确地指：在 \\(Q^T\\) 下 \\(\\ln F(T;T)\\) 正态。Black 公式在随机利率下仍然可用，只要对数正态写在 \\(Q^T\\) 上，\\(\\sigma\\) 是远期波动率。</p><p>多个到期 \\(\\{T_i\\}\\) 对应多个 \\(Q^{T_i}\\)，这是利率衍生的标准日历；本课只需要一个 \\(T\\)。</p><p><span class="marginnote">「远期价格是 \\(Q^T\\)-鞅」的直觉：用未来的钱（\\(T\\) 时刻到期的债）记账时，未来的价格没有系统性的涨跌倾向——今天锁定的远期价，就是对 \\(T\\) 时刻价格的无偏猜测，所以期望可以单独搬出来算。</span></p>',17)),(e(),i(T,null,{default:r(()=>[o(B,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%82%A8%E8%93%84%E8%B4%A6%E6%88%B7%E6%B5%8B%E5%BA%A6%20Q%22%5D%20--%3E%20BOND%5B%22%E9%9B%B6%E6%81%AF%E5%80%BA%E4%BD%9C%E8%AE%A1%E4%BB%B7%E7%89%A9%22%5D%0A%20%20BOND%20--%3E%20QT%5B%22T%20%E8%BF%9C%E6%9C%9F%E6%B5%8B%E5%BA%A6%22%5D%0A%20%20QT%20--%3E%20SEP%5B%22%E4%BB%B7%E6%A0%BC%E7%AD%89%E4%BA%8E%E5%80%BA%E4%BB%B7%E4%B9%98%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20SEP%20--%3E%20RATE%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9Ar%20%E9%9A%8F%E6%9C%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"计价物变换是 Girsanov 的有限维版本：密度等于两个计价物的价值比。随机积分的漂移按两者波动率之差平移。\\(Q\\) 下贴现债券有波动，所以 \\(W\\) 在 \\(Q^T\\) 下会改漂移；标的的远期波动率是相对波动，不是现货 \\(\\sigma\\) 的原样拷贝。常数 \\(r\\) 时 \\(P(t,T)=\\mathrm e^{-r(T-t)}\\) 确定性，\\(Q^T=Q\\)，本课退化成上一课。",-1)),a[5]||(a[5]=t("p",null,"数字支付 \\(1_{\\{S_T\\gt K\\}}\\) 的价格是 \\(P(t,T)Q^T(S_T\\gt K)\\)。这给了 \\(d_2\\) 在随机利率下的正确定义：它是远期测度概率，不是储蓄账户测度概率。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"常见误区：以为随机利率下把 Black 公式里的 \\(r\\) 换成「预期平均利率」就能凑合。实际是概率测度整个换了——数字期权价格是 \\(P(t,T)Q^T(S_T\\gt K)\\)，概率与贴现一起搬进了 \\(Q^T\\) 的坐标系，不是对旧公式的小修小补。")],-1)),(e(),i(T,null,{default:r(()=>[o(B,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%B8%B8%E6%95%B0%20r%EF%BC%9A%E8%B4%B4%E7%8E%B0%E5%9B%A0%E5%AD%90%E7%A1%AE%E5%AE%9A%22%5D%20--%3E%20A1%5B%22%E4%BB%B7%E6%A0%BC%20%3D%20e%5E%20-rT%20%E4%B9%98%20E%20of%20Q%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E8%B4%B4%E7%8E%B0%E6%8F%90%E5%87%BA%E6%9C%9F%E6%9C%9B%EF%BC%8CQ%5ET%20%3D%20Q%22%5D%0A%20%20B%5B%22%E9%9A%8F%E6%9C%BA%20r%EF%BC%9A1%2FB_T%20%E4%B8%8E%20H%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20B1%5B%22%E4%BB%B7%E6%A0%BC%20%3D%20P%20t%2CT%20%E4%B9%98%20E%20of%20Q%5ET%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E8%B4%B4%E7%8E%B0%E5%9C%A8%E6%9C%9F%E6%9C%9B%E5%A4%96%EF%BC%8Cd2%20%E6%98%AF%20Q%5ET%20%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HJM、LIBOR 市场模型，不写交换期权的 Margrabe 之外的多计价物。下一课只预告 \\(r\\) 不能再当常数，不把期限结构建完。后课默认：随机贴现时先换到 \\(Q^T\\)，再谈对数正态。下一课<a href="/quant/stochastic-rate-preview">利率不是常数</a>说明为何主干公式里的 \\(r\\) 会裂开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(T\\)-远期测度以 \\(P(\\cdot,T)\\) 为计价物，把贴现提出期望。</li><li>远期价格是 \\(Q^T\\)-鞅；Black 的对数正态写在 \\(Q^T\\) 上。</li><li>常数 \\(r\\) 时 \\(Q^T=Q\\)，与上一课重合。</li><li>\\(d_2\\) 是远期测度下的实值概率。</li><li>出处：Geman–El Karoui–Rochet 1995；Shreve SDE II 第 9 章。</li></ul>',4))])}const P=n(m,[["render",A]]);export{f as __pageData,P as default};
